<?php
if (isset($_GET['source'])) {
    $index = file_get_contents(__DIR__ . '/index.php');
    if (preg_match('~<li>\s*<div class="entry-title"><a href="inbox-time-machine.php">.*?<div class="blurb">.*?<a href="([^"]+)"~s', $index, $m)) {
        $url = html_entity_decode($m[1], ENT_QUOTES, 'UTF-8');
        if (filter_var($url, FILTER_VALIDATE_URL) && in_array(parse_url($url, PHP_URL_SCHEME), ['https','http'], true)) {
            header('Location: ' . $url, true, 302); exit;
        }
    }
    http_response_code(404); exit('Source link unavailable.');
}
?>
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Inbox Time Machine</title>
<style>
:root{--ink:#173d3d;--paper:#f5eddd;--red:#b93924;--teal:#1a6663;--gold:#e9bc58}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Trebuchet MS",Verdana,sans-serif;background-image:radial-gradient(#173d3d12 .7px,transparent .7px);background-size:7px 7px}
main{max-width:1280px;margin:auto;padding:26px 36px 40px}a{color:var(--teal)}button{font:inherit;cursor:pointer;min-height:46px;border:1px solid var(--ink);background:#fff8eb;color:var(--ink);padding:11px 16px;border-radius:3px}button:hover{background:#eddcbb}button:focus-visible,a:focus-visible{outline:3px solid var(--red);outline-offset:4px}button:disabled{cursor:default;opacity:.65}.eyebrow{font-family:"Courier New",monospace;text-transform:uppercase;font-size:12px;letter-spacing:2px}.top{display:flex;justify-content:space-between;gap:16px;border-bottom:2px solid var(--ink);padding-bottom:14px;align-items:center}.mast{display:grid;grid-template-columns:1.2fr 1fr;gap:50px;align-items:end;margin:36px 0}h1{font-family:Georgia,serif;font-size:clamp(48px,6vw,82px);font-weight:normal;letter-spacing:-3px;line-height:.93;margin:12px 0}h1 em{color:var(--red)}.intro{max-width:470px;line-height:1.65;font-size:17px}.workspace{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:28px}.monitor{border:2px solid var(--ink);border-radius:12px;background:#d9d6c8;box-shadow:7px 8px 0 #173d3d20;padding:14px;align-self:start}.switch{display:flex;gap:6px;margin-bottom:12px}.switch button{flex:1;font-size:13px}.switch button[aria-pressed=true]{background:var(--ink);color:var(--paper)}.mailhead{background:#eee9de;padding:13px 17px;font-family:"Courier New",monospace;font-size:12px;border-bottom:1px solid #c5c3b6;line-height:1.8}.mail{background:#fff;min-height:420px;color:#183d3d}.hero{height:190px;background:center 49% / cover var(--teal);position:relative}.hero img{width:100%;height:100%;object-fit:cover;object-position:center 49%;display:block}.lost{background:#f5f2e9;display:flex;justify-content:center;align-items:center;color:#736954;font-family:"Courier New",monospace;font-size:13px;text-align:center;padding:25px}.mailbody{padding:24px}.mailbody h2{font-family:Georgia,serif;font-size:30px;font-weight:normal;margin:0 0 18px}.columns{display:flex;gap:20px}.columns>div{flex:1;line-height:1.5;font-size:14px}.columns.stacked{display:block}.columns.stacked>div+div{margin-top:16px}.ticket{background:#f5eddd;padding:14px}.space{margin:22px 0}.space.squashed{margin:0}.cta{display:inline-block;padding:13px 22px;background:var(--red);color:white;font-weight:bold;border-radius:5px}.cta.broken{background:transparent;color:var(--red);padding:0;text-decoration:underline;border-radius:0}.cta.square{border-radius:0}.statusbar{display:flex;align-items:center;justify-content:space-between;font-size:12px;gap:12px;padding:14px 2px 2px}.dots{display:flex;gap:6px}.dots span{width:12px;height:12px;border:1px solid var(--ink);border-radius:50%;background:#eee9de}.dots span.done{background:var(--teal)}.bench{border-top:5px solid var(--red);padding-top:18px}.bench h2{font-family:Georgia,serif;font-size:29px;font-weight:normal;margin:8px 0}.brief{line-height:1.6;margin-bottom:20px}.choices{display:grid;gap:10px}.choices button{text-align:left;background:#fff9ee;line-height:1.4;box-shadow:2px 3px 0 #173d3d16}.choices button.correct{border-color:var(--teal);background:#d9e9de}.choices small{display:block;font-family:"Courier New",monospace;font-size:11px;color:#586a60;margin-top:5px}.feedback{min-height:86px;font-size:14px;line-height:1.6;padding:15px 0}.actions{display:flex;gap:10px;flex-wrap:wrap}.primary{background:var(--ink);color:var(--paper)}.primary:hover{background:var(--teal)}.note{font-size:12px;line-height:1.6;color:#536862}.receipt{background:#fff9ee;border-top:1px dashed var(--ink);margin-top:25px;padding:20px}.receipt h3{font-family:Georgia,serif;font-size:23px;margin:0 0 10px}.receipt li{font-size:14px;line-height:1.6;margin:8px 0}footer{border-top:1px solid var(--ink);margin-top:35px;padding-top:18px;font-size:13px;line-height:1.8}[hidden]{display:none!important}
@media(max-width:760px){main{padding:20px 17px}.mast{grid-template-columns:1fr;gap:8px;margin:26px 0}h1{letter-spacing:-2px}.intro{font-size:15px}.workspace{grid-template-columns:1fr;gap:26px}.monitor{padding:9px}.hero{height:165px}.top{font-size:12px}.top .eyebrow{letter-spacing:1px;font-size:10px}.mailbody{padding:19px}.mailbody h2{font-size:27px}.columns{gap:13px}.columns>div{font-size:13px}.bench{padding-top:13px}.feedback{min-height:70px}}
@media(prefers-reduced-motion:no-preference){.monitor{animation:arrive .7s ease-out}.bench{animation:arrive .9s ease-out}@keyframes arrive{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}}
</style></head><body><main>
<nav class="top"><a href="./">← Chloe Reads Jon</a><span class="eyebrow">Department of undelivered beauty / No. 007</span></nav>
<header class="mast"><div><div class="eyebrow">A tiny email rescue game</div><h1>Inbox<br><em>Time Machine.</em></h1></div><p class="intro">It looked lovely in your browser. Then it arrived in 2007.<br>Rescue a rocket-club invitation from four old Outlook traps. No timer. No shame. Just a very stubborn inbox.</p></header>
<div class="workspace"><section class="monitor" aria-label="Illustrated email preview">
<div class="switch" aria-label="Preview mode"><button id="modern" aria-pressed="false">Modern browser</button><button id="outlook" aria-pressed="true">Outlook 2007</button></div>
<div class="mailhead">FROM: The Paper Rocket Society<br>SUBJECT: Your seat on the next adventure</div>
<div class="mail"><div id="hero" class="hero"></div><div class="mailbody"><h2>A small envelope.<br>A very big adventure.</h2><div id="columns" class="columns"><div>Join our tiny rocket exhibition. Bring your curiosity; we’ll bring the cardboard, brass rivets, and unreasonable optimism.</div><div class="ticket"><strong>Launch night</strong><br>Saturday · 4 pm<br>Paper City Hangar<br>One curious human per ticket</div></div><p id="spacing" class="space">Your boarding pass is waiting. The rocket is mostly stationery. The excitement is entirely real.</p><span id="cta" class="cta">Reserve my seat →</span></div></div>
<div class="statusbar"><span id="modeLabel">Word-based rendering · illustrated simulation</span><div class="dots" aria-label="Repair progress"><span></span><span></span><span></span><span></span></div></div>
</section>
<section class="bench"><div class="eyebrow" id="caseLabel"></div><h2 id="title"></h2><p class="brief" id="brief"></p><div class="choices" id="choices"></div><div class="feedback" id="feedback" role="status" aria-live="polite"></div><div class="actions"><button id="next" class="primary" hidden>Next repair →</button><button id="hint">A small hint</button><button id="reset">Start over</button></div><p class="note">A teaching model, not an Outlook emulator or complete email validator. We exaggerate selected failures so you can see them. Preview controls never send email.</p><div class="receipt" id="receipt" hidden><h3>Cleared for takeoff.</h3><p>Four repairs, one invitation that survives the journey.</p><ul><li>Use an ordinary image when you don’t need text over it.</li><li>Use presentation tables for dependable legacy columns.</li><li>Put reliable spacing on table cells.</li><li>Style a link inside a coloured table cell; square corners are fine.</li></ul><button id="copy">Copy my repair notes</button><p class="note" id="copyStatus" role="status"></p></div></section></div>
<footer>Inspired by Jon’s <a href="?source=1">Outlook HTML Email Online Validator</a> (2011).<br>Original rocket-post illustration made for this experiment. All play happens right here.</footer>
</main><script>
const art='data:image/webp;base64,';
const cases=[
{title:'The missing rocket',brief:'The invitation’s header used a CSS background image. In our old inbox, the picture vanished. We don’t need any text over it. What should carry the art?',options:[['Make the background !important','background-image: … !important'],['Use a regular image element','<img width="600" alt="A rocket delivering a letter">'],['Put the picture in a pseudo-element','::before { background-image: … }']],answer:1,hint:'Give the picture its own place in the document, rather than asking CSS to paint it.',yes:'The rocket is back. An ordinary image works for this header. Backgrounds behind live text are a different job and may need Outlook-specific VML.',no:'That still relies on unsupported CSS. Try giving the illustration its own HTML element.'},
{title:'Two columns, one pile',brief:'Our invitation uses flexbox. Outlook 2007 uses Microsoft Word to render HTML, not a modern browser. How can we keep the two columns together?',options:[['Turn up the flex strength','display:flex !important'],['Switch to CSS Grid','display:grid; grid-template-columns:1fr 1fr'],['Use a two-cell presentation table','<table role="presentation"><tr><td>…</td><td>…</td></tr></table>']],answer:2,hint:'Think of the sturdy layout technique people used before flexbox existed.',yes:'The exhibition and boarding details sit side by side again. Presentation tables are still a practical tool for legacy HTML email, even though they aren’t the usual choice for web-page layout.',no:'Word does not gain a modern layout engine from more CSS. Try the dependable old-fashioned structure.'},
{title:'Give the words some air',brief:'The paragraph’s generous CSS margins collapse in our simplified preview. We want a reliable 22-pixel gap in a legacy email. Where should that spacing live?',options:[['On a table cell as padding','<td style="padding:22px 0">…</td>'],['In a flex gap','gap:22px'],['In six empty paragraphs','<p></p><p></p>…']],answer:0,hint:'Choose explicit spacing on the same sturdy structure that holds the columns.',yes:'Room to breathe. Cell padding is a dependable way to build email spacing. Real Outlook margin behaviour varies by element; the lesson is to choose the structure deliberately.',no:'That is either unsupported or unpredictable. Empty paragraphs also make the document noisier for readers and assistive technology.'},
{title:'The disappearing button',brief:'The call to action was an HTML button with rounded corners. Old Outlook is not a place to depend on form controls or border-radius. How do we make a useful, sturdy email call to action?',options:[['Use an onclick handler','<button onclick="reserve()">Reserve</button>'],['Use a link in a coloured table cell','<td bgcolor="…"><a href="relative-path">Reserve</a></td>'],['Replace it with an image only','A picture of a button, with no link']],answer:1,hint:'Email calls to action are links. Keep the label as real text, and let the container provide its colour.',yes:'A sturdy square-cornered call to action. For reliably rounded “bulletproof” buttons, production emails often use an Outlook-specific VML fallback. Our invitation is happy to be square.',no:'Email clients usually strip scripts, and an unlinked picture cannot take you anywhere. Keep the action as a real text link.'}
];
let current=0,modern=false,fixed=[false,false,false,false];
const $=id=>document.getElementById(id);
function preview(){
const works=i=>modern||fixed[i];
$('hero').className=works(0)?'hero':'hero lost';
$('hero').replaceChildren();
if(works(0)){const img=new Image();img.src=art;img.alt='A tin rocket delivers a letter above a teal and coral paper city.';$('hero').append(img)}else $('hero').textContent='[ CSS background image did not arrive ]';
$('columns').className='columns'+(works(1)?'':' stacked');
$('spacing').className='space'+(works(2)?'':' squashed');
$('cta').className='cta'+(!works(3)?' broken':(!modern?' square':''));
$('modern').setAttribute('aria-pressed',String(modern));$('outlook').setAttribute('aria-pressed',String(!modern));
$('modeLabel').textContent=modern?'Browser reference · selected fixes also apply':'Word-based rendering · illustrated simulation';
document.querySelectorAll('.dots span').forEach((d,i)=>d.classList.toggle('done',fixed[i]));
}
function show(){
const c=cases[current];$('caseLabel').textContent='Repair '+(current+1)+' / 4';$('title').textContent=c.title;$('brief').textContent=c.brief;$('feedback').textContent=fixed[current]?c.yes:'Choose a repair. Switch previews to compare what survived.';
$('choices').replaceChildren();c.options.forEach((o,i)=>{const b=document.createElement('button');b.textContent=o[0];const code=document.createElement('small');code.textContent=o[1];b.append(code);b.disabled=fixed[current];if(fixed[current]&&i===c.answer)b.classList.add('correct');b.addEventListener('click',()=>choose(i));$('choices').append(b)});
$('next').hidden=!fixed[current]||current===3;$('hint').hidden=fixed[current];$('receipt').hidden=!fixed.every(Boolean);preview();
}
function choose(i){const c=cases[current];if(i!==c.answer){$('feedback').textContent=c.no;return}fixed[current]=true;modern=false;show()}
$('modern').onclick=()=>{modern=true;preview()};$('outlook').onclick=()=>{modern=false;preview()};
$('hint').onclick=()=>{$('feedback').textContent=cases[current].hint};
$('next').onclick=()=>{if(current<3){current++;show();$('title').setAttribute('tabindex','-1');$('title').focus({preventScroll:true})}};
$('reset').onclick=()=>{current=0;modern=false;fixed=[false,false,false,false];$('copyStatus').textContent='';show()};
$('copy').onclick=async()=>{const text='Inbox Time Machine: legacy email repair notes\n1. Ordinary image elements for non-overlay artwork.\n2. Presentation tables for legacy columns.\n3. Explicit table-cell padding for reliable spacing.\n4. Real text links inside coloured cells for calls to action.\nAlways test in the actual email clients you support.';try{await navigator.clipboard.writeText(text);$('copyStatus').textContent='Repair notes copied.'}catch(e){$('copyStatus').textContent='Clipboard unavailable. Your repair notes are listed above; you can select and copy them.'}};
show();
</script></body></html>
